// === Tab: circle ===
function Circle(x, y) {

	this.rad = floor(random(2,100));

	// creates some circle bodies 

	let ballParams = {
  	restitution: 0.0,
		density:0.001,
		friction:0.0,
		size:this.rad,
		frictionStatic:0.5,
    frictionAir: 0.1,
		sides:4,
		chamfer:0,
  }

	this.body = Bodies.circle(x, y,this.rad/2,ballParams);

	this.rand = random(0,1);

	this.color1 = generateColor(10);
	this.color2 = generateColor(10);

	World.add(world, this.body);

	this.show = function() {
		let pos = this.body.position;
		fill(this.color1);
		if(this.rand < 0.1)
		{
	   	strokeWeight(1);
		  stroke(this.color2);
		}
		blurredCircle(pos.x,pos.y,this.rad,this.color1);
		fill(this.color2);
		blurredCircle(pos.x,pos.y,this.rad/2,this.color2);
	}
}

function blurredCircle(x,y,rad,myCol)
{

	for(r = 0; r < rad;r+=10)
	{
		let transp = map(r,0,rad,90,0);
		fill(0,0,0,transp);
		stroke(0,0,0,transp);
		ellipse(x,y,r,r);
	}

	fill(myCol);
	noStroke();
	ellipse(x,y,rad - rad*0.25,rad - rad*0.25);
}


